-- Runs before project collectors. NNES_CAPTURE is generated by nnes-capture.
local config = NNES_CAPTURE
local out = config.output
local frame = 0
local stopped = false
local access_count = 0
local trace = nil
local original_stop = emu.stop

local function quote(value)
    return '"' .. tostring(value):gsub('[%z\1-\31\\"]', function(c)
        if c == '\\' then return '\\\\' end
        if c == '"' then return '\\"' end
        return string.format('\\u%04x', string.byte(c))
    end) .. '"'
end

local function json_object(value)
    local keys, items = {}, {}
    for key in pairs(value) do keys[#keys + 1] = key end
    table.sort(keys)
    for _, key in ipairs(keys) do
        local item = value[key]
        local kind = type(item)
        assert(kind == 'number' or kind == 'string' or kind == 'boolean',
               'unsupported state value: ' .. tostring(key))
        items[#items + 1] = quote(key) .. ':' ..
            (kind == 'string' and quote(item) or tostring(item))
    end
    return '{' .. table.concat(items, ',') .. '}'
end

local function write_json(name, value)
    local file = assert(io.open(out .. '/' .. name, 'wb'))
    assert(file:write(json_object(value) .. '\n'))
    assert(file:close())
end

-- The profile and private collectors use this directory or the supplied env.
emu.getScriptDataFolder = function() return out end

local function finish(code, reason)
    if stopped then return end
    stopped = true
    if trace then
        trace:write('{"type":"footer","access_count":' .. access_count .. '}\n')
        assert(trace:close())
    end
    write_json('state.json', emu.getState())
    write_json('completion.json', {version=1, code=code, reason=reason,
        frames=frame, access_count=access_count,
        rom_sha1=emu.getRomInfo().fileSha1Hash:lower()})
    original_stop(code)
end

emu.stop = function(code) finish(code or 0, 'script_stop') end

emu.addEventCallback(function()
    if stopped or config.script_input then return end
    for port = 1, 2 do
        local buttons = config.input[frame + 1] and config.input[frame + 1][port] or {}
        local state = {a=false,b=false,select=false,start=false,
                       up=false,down=false,left=false,right=false}
        for _, button in ipairs(buttons) do state[button:lower()] = true end
        emu.setInput(state, port - 1, 0)
    end
end, emu.eventType.inputPolled)

if config.trace then
    assert(emu.memoryOperationType, 'typed-operation patch is required')
    local names = {}
    for key, value in pairs(emu.memoryOperationType) do names[value] = key end
    trace = assert(io.open(out .. '/bus.jsonl', 'wb'))
    trace:write('{"type":"header","format":"nnes-typed-bus-trace","version":1,' ..
                '"rom_sha1":' .. quote(emu.getRomInfo().fileSha1Hash:lower()) .. '}\n')
    local function access(address, value, operation)
        if stopped then return end
        if access_count >= config.max_events then
            finish(66, 'event_limit')
            return
        end
        assert(names[operation], 'missing typed memory operation')
        trace:write(string.format(
            '{"type":"access","event":%d,"frame":%d,"cycle":%.0f,' ..
            '"master_clock":%.0f,"operation":%s,"address":%d,"value":%d}\n',
            access_count, frame, emu.getCpuCycleCount(emu.cpuType.nes),
            emu.getMasterClock(), quote(names[operation]), address, value))
        access_count = access_count + 1
    end
    for _, kind in ipairs({emu.callbackType.read, emu.callbackType.write,
                           emu.callbackType.exec}) do
        emu.addMemoryCallback(access, kind, 0, 0xFFFF, emu.cpuType.nes,
                              emu.memType.nesMemory)
    end
end

emu.addEventCallback(function()
    if stopped then return end
    frame = frame + 1
    if frame >= config.frame_limit then
        -- A custom collector must finish itself; reaching its ceiling is failure.
        finish(config.must_stop and 66 or 0, 'frame_limit')
    end
end, emu.eventType.endFrame)
